def get_minimal_good_set(x, y, limit=10000):
    s = {x, y}
    # We also know x^2, y^2, ... are in X.
    # And for any a in X, k*a^2 is in X.
    # Let's maintain a set of "generators" to avoid explosion.
    generators = {x, y}

    # Let's use a simpler approach.
    # A good set must contain:
    # 1. x, y
    # 2. For any a, b in X, a^2 + i*a*b + b^2 in X
    # 3. For any a in X, k*a^2 in X

    # This is equivalent to:
    # X is the smallest set containing x, y such that:
    # a, b in X => a^2 + iab + b^2 in X

    # Let's just use a set and iterate.
    # To keep it small, we'll only keep elements whose absolute value is < limit.

    current_set = {x, y}
    new_elements = {x, y}

    while new_elements:
        next_elements = set()
        for a in current_set:
            # Case: a, a in X
            # a^2 + i*a*a + a^2 = (i+2)a^2
            a2 = a*a
            if a2 != 0:
                for k in range(-limit // a2, limit // a2 + 1):
                    val = k * a2
                    if abs(val) < limit and val not in current_set:
                        next_elements.add(val)

            # Case: a, b in X
            for b in current_set:
                if a == b: continue
                # We'll check i in a reasonable range.
                # But wait, i can be any integer.
                # However, if |a^2 + iab + b^2| is very large, we don't care.
                # a^2 + iab + b^2 is roughly i*ab.
                # So |i| should be up to limit / |ab|.
                if a * b != 0:
                    limit_i = limit // abs(a * b) + 2
                    for i in range(-limit_i, limit_i + 1):
                        val = a*a + i*a*b + b*b
                        if abs(val) < limit and val not in current_set:
                            next_elements.add(val)
                else:
                    # If a=0 or b=0
                    # if a=0, 0 + 0 + b^2 = b^2.
                    val = b*b
                    if abs(val) < limit and val not in current_set:
                        next_elements.add(val)

        if not next_elements:
            break
        current_set.update(next_elements)
        new_elements = next_elements
        if 1 in current_set or -1 in current_set:
            return current_set

    return current_set

def is_complex_pair(x, y):
    # (x, y) is a complex pair if there's a good set X s.t. x, y in X and X != Z
    # This is true if the minimal good set X_xy != Z.
    # The minimal good set X_xy != Z if and only if 1 not in X_xy.
    res = get_minimal_good_set(x, y)
    return 1 not in res

