def is_good_number(m):
    # Check if there exist x, y such that x^2 + y^2 = m, x != y, x, y > 0, and gcd(x, y) > 1
    for x in range(1, int(math.sqrt(m/2)) + 1):
        y2 = m - x*x
        if y2 <= 0:
            continue
        y = int(math.isqrt(y2))
        if y*y == y2:
            if x != y and math.gcd(x, y) > 1:
                return True
    return False

