import math

def get_minimal_good_set_elements(x, y, limit=1000):
    # Elements that MUST be in the good set.
    # 1. x, y
    # 2. If a in X, then k*a^2 in X
    # 3. If a, b in X, then a^2 + iab + b^2 in X

    s = {x, y}
    new_elements = {x, y}

    while new_elements:
        next_elements = set()
        # Rule 2: k*a^2
        for a in s:
            if a == 0: continue
            a2 = a*a
            for k in range(-limit // a2, limit // a2 + 1):
                val = k * a2
                if abs(val) < limit and val not in s:
                    next_elements.add(val)

        # Rule 3: a^2 + iab + b^2
        for a in s:
            for b in s:
                if a == 0 or b == 0:
                    # if a=0, then 0 + 0 + b^2 = b^2
                    val = b*b
                    if abs(val) < limit and val not in s:
                        next_elements.add(val)
                    continue

                # a^2 + iab + b^2
                # We need to check i such that |a^2 + iab + b^2| < limit
                # i*ab is roughly limit, so i is roughly limit/(ab)
                limit_i = limit // abs(a * b) + 2
                for i in range(-limit_i, limit_i + 1):
                    val = a*a + i*a*b + b*b
                    if abs(val) < limit and val not in s:
                        next_elements.add(val)

        if not next_elements:
            break
        s.update(next_elements)
        new_elements = next_elements
        if 1 in s or -1 in s:
            return s
    return s

